              hash: 'old0001',
              fullHash: '1111111111111111111111111111111111111111',
              author: 'older',
              date: '2026/9/1',
              dateTime: '2026/9/1 8:00',
              summary: 'feat: 更早',
              content: line.content,
              previousRevision: '',
