        head: [...document.querySelectorAll('.log-ref-panel .tree-row[data-ref-kind="head"]')].map((n) => n.textContent.trim()),
        groups: [...document.querySelectorAll('.log-ref-panel .tree-row.group-row')].map((n) => n.textContent.trim()),
