      await scene.page.waitForTimeout(200);
      const keyCollapsed = await groupState();
      await scene.page.keyboard.press('ArrowRight');
      await scene.page.waitForTimeout(200);
      const keyExpanded = await groupState();
      // 竖条的「全部折叠／全部展开」作用在**所有**分组上。
