      const t17 = await termMetrics(17);
      const ratio13 = t13.rowHeight && t13.fontSize ? +(t13.rowHeight / t13.fontSize).toFixed(3) : null;
      const ratio17 = t17.rowHeight && t17.fontSize ? +(t17.rowHeight / t17.fontSize).toFixed(3) : null;
